def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    def tokenize(s: str) -> list[tuple[str, str | int]]:
        tokens: list[tuple[str, str | int]] = []
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if ch.isspace():
                i += 1
            elif ch.isdigit():
                j = i + 1
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(("NUM", int(s[i:j])))
                i = j
            elif "A" <= ch <= "Z":
                j = i + 1
                while j < n and ("A" <= s[j] <= "Z" or s[j].isdigit()):
                    j += 1
                word = s[i:j]
                if word in ("SUM", "MIN", "MAX", "IF"):
                    tokens.append(("FUNC", word))
                else:
                    tokens.append(("CELL", word))
                i = j
            elif ch == "<":
                if i + 1 < n and s[i + 1] in (">", "="):
                    tokens.append(("OP", s[i : i + 2]))
                    i += 2
                else:
                    tokens.append(("OP", "<"))
                    i += 1
            elif ch == ">":
                if i + 1 < n and s[i + 1] == "=":
                    tokens.append(("OP", ">="))
                    i += 2
                else:
                    tokens.append(("OP", ">"))
                    i += 1
            elif ch == "=":
                tokens.append(("OP", "="))
                i += 1
            else:
                tokens.append((ch, ch))
                i += 1
        return tokens

    def parse(formula: str) -> tuple:
        tokens = tokenize(formula)
        pos = 0
        n = len(tokens)

        def parse_expr() -> tuple:
            nonlocal pos
            node = parse_term()
            while pos < n and tokens[pos][0] in ("+", "-"):
                op = tokens[pos][0]
                pos += 1
                node = ("binop", op, node, parse_term())
            return node

        def parse_term() -> tuple:
            nonlocal pos
            node = parse_unary()
            while pos < n and tokens[pos][0] in ("*", "/"):
                op = tokens[pos][0]
                pos += 1
                node = ("binop", op, node, parse_unary())
            return node

        def parse_unary() -> tuple:
            nonlocal pos
            if pos < n and tokens[pos][0] == "-":
                pos += 1
                return ("neg", parse_unary())
            return parse_atom()

        def parse_atom() -> tuple:
            nonlocal pos
            kind, val = tokens[pos]
            if kind == "NUM":
                pos += 1
                return ("num", val)
            if kind == "CELL":
                pos += 1
                return ("cell", val)
            if kind == "(":
                pos += 1
                node = parse_expr()
                pos += 1
                return node
            func = val
            pos += 2
            if func == "IF":
                left = parse_expr()
                op = tokens[pos][1]
                pos += 1
                right = parse_expr()
                pos += 1
                then_node = parse_expr()
                pos += 1
                else_node = parse_expr()
                pos += 1
                return ("if", left, op, right, then_node, else_node)
            args = []
            while True:
                if (
                    pos + 1 < n
                    and tokens[pos][0] == "CELL"
                    and tokens[pos + 1][0] == ":"
                ):
                    c1_name = str(tokens[pos][1])
                    c2_name = str(tokens[pos + 2][1])
                    pos += 3
                    c1, r1 = ord(c1_name[0]) - 65, int(c1_name[1:])
                    c2, r2 = ord(c2_name[0]) - 65, int(c2_name[1:])
                    if c1 > c2:
                        c1, c2 = c2, c1
                    if r1 > r2:
                        r1, r2 = r2, r1
                    args.append(("range", c1, r1, c2, r2))
                else:
                    args.append(("expr", parse_expr()))
                if tokens[pos][0] == ",":
                    pos += 1
                else:
                    pos += 1
                    break
            return ("agg", func, args)

        return parse_expr()

    def eval_node(node: tuple):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "cell":
            return (yield node[1])
        if kind == "neg":
            v = yield from eval_node(node[1])
            if isinstance(v, str):
                return v
            return -v
        if kind == "binop":
            _, op, left, right = node
            lv = yield from eval_node(left)
            if isinstance(lv, str):
                return lv
            rv = yield from eval_node(right)
            if isinstance(rv, str):
                return rv
            if op == "+":
                return lv + rv
            if op == "-":
                return lv - rv
            if op == "*":
                return lv * rv
            if rv == 0:
                return "#DIV/0!"
            q = abs(lv) // abs(rv)
            return -q if (lv < 0) ^ (rv < 0) else q
        if kind == "if":
            _, left, op, right, then_node, else_node = node
            lv = yield from eval_node(left)
            if isinstance(lv, str):
                return lv
            rv = yield from eval_node(right)
            if isinstance(rv, str):
                return rv
            if op == "=":
                cond = lv == rv
            elif op == "<>":
                cond = lv != rv
            elif op == "<":
                cond = lv < rv
            elif op == "<=":
                cond = lv <= rv
            elif op == ">":
                cond = lv > rv
            else:
                cond = lv >= rv
            return (yield from eval_node(then_node if cond else else_node))

        _, func, args = node
        has_val = False
        acc = 0
        for arg in args:
            if arg[0] == "range":
                _, c1, r1, c2, r2 = arg
                for r in range(r1, r2 + 1):
                    for c in range(c1, c2 + 1):
                        cname = f"{chr(65 + c)}{r}"
                        if cname not in cells:
                            continue
                        v = yield cname
                        if isinstance(v, str):
                            return v
                        if func == "SUM":
                            acc += v
                        elif not has_val:
                            acc = v
                            has_val = True
                        elif func == "MIN":
                            if v < acc:
                                acc = v
                        elif v > acc:
                            acc = v
            else:
                v = yield from eval_node(arg[1])
                if isinstance(v, str):
                    return v
                if func == "SUM":
                    acc += v
                elif not has_val:
                    acc = v
                    has_val = True
                elif func == "MIN":
                    if v < acc:
                        acc = v
                elif v > acc:
                    acc = v
        return acc if (func == "SUM" or has_val) else 0

    results: dict[str, int | str] = {}
    asts: dict[str, tuple] = {}
    for name, content in cells.items():
        if content.startswith("="):
            asts[name] = parse(content[1:])
        else:
            results[name] = int(content)

    visiting: set[str] = set()
    for name in cells:
        if name in results:
            continue
        visiting.add(name)
        stack: list[list] = [[name, eval_node(asts[name]), None]]
        while stack:
            cname, gen, to_send = stack[-1]
            try:
                target = gen.send(to_send)
            except StopIteration as e:
                val = e.value
                stack.pop()
                visiting.remove(cname)
                results[cname] = val
                if stack:
                    stack[-1][2] = val
                continue
            if target not in cells:
                stack[-1][2] = 0
            elif target in results:
                stack[-1][2] = results[target]
            elif target in visiting:
                stack[-1][2] = "#CYCLE!"
            else:
                visiting.add(target)
                stack.append([target, eval_node(asts[target]), None])

    return results
